-- P99-reviewed Velious content. Quest faction gates deliberately bypassed; actual faction rewards retained.
local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") then
    e.self:Say("Uuuuhhh, how goes it, " .. e.other:GetRaceName() .. "? Oh, I'm doin' jest fine down here, just hanging around... Mining! Yes mining for our fearless leader, the Dain. Yessiree... sssoooooo...")
  end
end

function event_trade(e)
  if item_lib.check_turn_in(e.trade, { item1 = 1725 }) then
    e.self:Emote("Hmmm, not sure why you're giving me all this. <cough> 50 pieces <cough> of platinum <cough> Whew, wow, I may be coming down with <cough> and the note <cough> something.")
    eq.set_global("shipment", "1", 0, "D1")
  elseif eq.get_qglobals()["shipment"] == "1" and item_lib.check_turn_in(e.trade, { platinum = 50 }) then
    e.self:Emote("takes the platinum and hands you a shipment of velium ore.")
    e.other:SummonItem(29064)
    eq.del_global("shipment")
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end
